      ...data,
      run_id: runId,
      ts: new Date().toISOString(),
      seq,
    })
  }

  async function play(frames: Frame[]): Promise<void> {
    for (const frame of frames) {
      if (signal.aborted) throw abortError()
      await sleep(frame.delay ?? frameDelay, signal)
      if (signal.aborted) throw abortError()
      emit(frame.event, frame.data)
